hooks.command:
INPUT=$(cat)
if command -v jq >/dev/null 2>&1; then
  CMD=$(printf '%s' "$INPUT" | jq -r '.tool_input.command // empty' 2>/dev/null) J=0
else
  CMD=$(printf '%s' "$INPUT" | sed -nE 's/.*"command"[[:space:]]*:[[:space:]]*"(([^"\\]|\\.)*)".*/\1/p') J=1
fi
[ -n "$CMD" ] || exit 0
# Split the command the way sh does (quotes, escapes, heredocs, $(...), separators), unwrap
# env/xargs/sudo/nohup/time/command/exec/nice/timeout/eval and sh -c, then judge each argv.
# Text that is only data (heredoc bodies, echo/printf args, grep patterns, git/gh messages) is not a command.
OUT=$(printf '%s\n' "$CMD" | awk -v J="$J" '
function bn(w) { sub(/.*\//, "", w); return w }
function isasg(w) { return w ~ /^[A-Za-z_][A-Za-z0-9_]*=/ }
function issec(w) { return match(w, SECRE) }
function chk(w) { if (HIT == "" && issec(w)) HIT = substr(w, RSTART, RLENGTH) }
function pend(d, k, i, s, L, c, dep, q) {
  dep = 1; q = ""
  for (; k <= LC[d]; k++) {
    s = LS[d, k]; L = length(s)
    for (; i <= L; i++) {
      c = substr(s, i, 1)
      if (q == SQ) { if (c == SQ) q = ""; continue }
      if (c == "\\") { i++; continue }
      if (q == DQ) { if (c == DQ) q = ""; continue }
      if (c == SQ || c == DQ) q = c
      else if (c == "(") dep++
      else if (c == ")" && --dep == 0) { EK = k; EI = i; return }
    }
    i = 1
  }
  EK = LC[d]; EI = length(LS[d, EK]) + 1
}
function bend(d, k, i, s, L, c) {
  for (; k <= LC[d]; k++) {
    s = LS[d, k]; L = length(s)
    for (; i <= L; i++) { c = substr(s, i, 1); if (c == "\\") i++; else if (c == "`") { EK = k; EI = i; return } }
    i = 1
  }
  EK = LC[d]; EI = length(LS[d, EK]) + 1
}
function grab(d, k, i, n, j) {
  if (k == EK) { LS[d + 1, 1] = substr(LS[d, k], i, EI - i); n = 1 }
  else {
    LS[d + 1, 1] = substr(LS[d, k], i); n = 1
    for (j = k + 1; j < EK; j++) LS[d + 1, ++n] = LS[d, j]
    LS[d + 1, ++n] = substr(LS[d, EK], 1, EI - 1)
  }
  LC[d + 1] = n; parse(d + 1)
}
function parsestr(t, d, n, i) { n = split(t, SPL, "\n"); for (i = 1; i <= n; i++) LS[d, i] = SPL[i]; LC[d] = n; parse(d) }
function subs(d, k, s, L, i, j, c, nk, ni) {
  for (k = 1; k <= LC[d]; k++) {
    s = LS[d, k]; L = length(s)
    for (i = 1; i <= L; i++) {
      if (!(j = match(substr(s, i), /[\\$`]/))) break
      i += j - 1; c = substr(s, i, 1)
      if (c == "\\") { i++; continue }
      if (c == "`") bend(d, k, i + 1)
      else if (substr(s, i + 1, 1) == "(") pend(d, k, i + 2)
      else continue
      nk = EK; ni = EI; grab(d, k, i + (c == "`" ? 1 : 2)); k = nk; i = ni; s = LS[d, k]; L = length(s)
    }
  }
}
function endw(d, w, inw, wq, k) {
  if (!inw) return
  if (PF[d] == "H" || PF[d] == "T") {
    k = ++HN[d]; HD[d, k] = w; HQ[d, k] = wq; HT[d, k] = (PF[d] == "T"); PF[d] = ""; return
  }
  k = ++N[d]; W[d, k] = w; F[d, k] = PF[d]; PF[d] = ""
}
function endseg(d) { SK = ""; if (N[d]) seg(d); if (SK == "sh") LK[d] = "sh"; else if (SK == "interp" && LK[d] == "") LK[d] = "interp"; N[d] = 0; PF[d] = "" }
function heredocs(d, k, h, n, line) {
  for (h = 1; h <= HN[d]; h++) {
    n = 0
    for (; k <= LC[d]; k++) {
      line = LS[d, k]; if (HT[d, h]) sub(/^\t+/, "", line)
      if (line == HD[d, h]) { k++; break }
      LS[d + 1, ++n] = line
      if (LK[d] == "interp") chk(line)
    }
    LC[d + 1] = n
    if (LK[d] == "sh") parse(d + 1)
    else if (!HQ[d, h]) subs(d + 1)
  }
  HN[d] = 0
  return k
}
function parse(d, k, s, L, i, j, c, nx, w, inw, q, wq, cont, nk, ni) {
  if (d > 16) { BAD = 1; return }
  N[d] = 0; HN[d] = 0; PF[d] = ""; LK[d] = ""
  w = ""; inw = 0; q = ""; wq = 0
  for (k = 1; k <= LC[d]; k++) {
    s = LS[d, k]; L = length(s); cont = 0
    for (i = 1; i <= L; i++) {
      c = substr(s, i, 1)
      if (q == SQ) {
        if (!(j = index(substr(s, i), SQ))) { w = w substr(s, i); break }
        w = w substr(s, i, j - 1); i += j - 1; q = ""; continue
      }
      nk = 0
      if (c == "$" && substr(s, i + 1, 1) == "(") { pend(d, k, i + 2); nk = EK; ni = EI; grab(d, k, i + 2) }
      else if (c == "`") { bend(d, k, i + 1); nk = EK; ni = EI; grab(d, k, i + 1) }
      else if (q == "" && (c == "<" || c == ">") && substr(s, i + 1, 1) == "(") { pend(d, k, i + 2); nk = EK; ni = EI; grab(d, k, i + 2) }
      if (nk) { k = nk; i = ni; s = LS[d, k]; L = length(s); w = w "$()"; inw = 1; continue }
      if (q == DQ) {
        if (c == DQ) q = ""
        else if (c == "\\") { if (i == L) cont = 1; else { nx = substr(s, ++i, 1); w = w (index("$`\"\\", nx) ? "" : c) nx } }
        else { if (!(j = match(substr(s, i + 1), /[\"\\$`]/))) j = L - i + 1; w = w substr(s, i, j); i += j - 1 }
        continue
      }
      if (c == "\\") { if (i == L) cont = 1; else { w = w substr(s, ++i, 1); inw = wq = 1 } continue }
      if (c == SQ || c == DQ) { q = c; inw = wq = 1; continue }
      if (c == " " || c == "\t" || c == "\r") { endw(d, w, inw, wq); w = ""; inw = wq = 0; continue }
      if (c == "#" && !inw) break
      if (c == "<" || c == ">") {
        nx = substr(s, i + 1, 1)
        if (inw && !wq && w ~ /^[0-9]+$/) { w = ""; inw = 0 } else { endw(d, w, inw, wq); w = ""; inw = wq = 0 }
        if (c == "<" && nx == "<") {
          if (substr(s, i + 2, 1) == "<") { i += 2; PF[d] = "D"; continue }
          i++; if (substr(s, i + 1, 1) == "-") { i++; PF[d] = "T" } else PF[d] = "H"
          continue
        }
        if (nx == ">" || nx == "&" || nx == "|" || (c == "<" && nx == ">")) i++
        PF[d] = "R"; continue
      }
      if (c == ";" || c == "&" || c == "|" || c == "(" || c == ")") { endw(d, w, inw, wq); w = ""; inw = wq = 0; endseg(d); continue }
      w = w c; inw = 1
    }
    if (cont) continue
    if (q != "") { w = w "\n"; continue }
    endw(d, w, inw, wq); w = ""; inw = wq = 0; endseg(d)
    if (HN[d]) k = heredocs(d, k + 1) - 1
    LK[d] = ""
  }
  endw(d, w, inw, wq); endseg(d)
}
function rest(d, i, na, t) { t = ""; for (; i <= na; i++) t = t " " A[d, i]; return t }
function seg(d, n, na, i, j, s, e, w, b, cmd, hasc, np, cl, prev, irr, p1, p2) {
  n = N[d]; na = 0
  for (i = 1; i <= n; i++) {
    if (F[d, i] == "R") chk(W[d, i])
    else if (F[d, i] != "D") { A[d, ++na] = W[d, i]; EX[d, na] = 0 }
  }
  s = 1; e = na
  for (;;) {
    if (s > e) return
    w = A[d, s]; b = bn(w)
    if (isasg(w) || w ~ /^(!|\{|\}|if|then|else|elif|do|while|until|--)$/ || b == "nohup") s++
    else if (b == "env") {
      for (s++; s <= e && (A[d, s] ~ /^-/ || isasg(A[d, s])); s++) {
        if (A[d, s] ~ /^(-S|--split-string)$/) { EX[d, s + 1] = 1; parsestr(A[d, s + 1] rest(d, s + 2, e), d + 1); SK = ""; return }
        if (A[d, s] ~ /^(-u|-C|--unset|--chdir)$/) s++
      }
    } else if (b == "xargs" || b == "sudo" || b == "doas" || b == "exec" || b == "time" || b == "nice" || b == "timeout" || b == "stdbuf") {
      for (s++; s <= e && A[d, s] ~ /^-/; s++) {
        if (A[d, s] == "--") { s++; break }
        if (b == "xargs" && A[d, s] ~ /^(-[ILnPsdEaJRS]|--(arg-file|delimiter|eof|max-lines|max-args|max-procs|max-chars|process-slot-var))$/) s++
        if ((b == "sudo" || b == "doas") && A[d, s] ~ /^-[ugCDhpRrtTU]$/) s++
        if ((b == "exec" && A[d, s] == "-a") || (b == "time" && A[d, s] ~ /^-[fo]$/) || (b == "nice" && A[d, s] == "-n") || (b == "timeout" && A[d, s] ~ /^-[sk]$/) || (b == "stdbuf" && A[d, s] ~ /^-[ioe]$/)) s++
      }
      if (b == "timeout") s++
    } else if (b == "command") {
      s++; if (A[d, s] == "-p") s++
      if (A[d, s] ~ /^-[vV]/) return
    } else if (b == "eval") {
      for (i = s + 1; i <= e; i++) EX[d, i] = 1
      parsestr(rest(d, s + 1, e), d + 1); SK = ""; return
    } else if (b ~ /^(sh|bash|dash|zsh|ksh|ash)$/) {
      hasc = 0
      for (j = s + 1; j <= e && A[d, j] ~ /^[-+]/; j++) {
        if (A[d, j] == "--") { j++; break }
        if (A[d, j] ~ /^[-+][oO]$/) j++
        else if (A[d, j] ~ /^-[A-Za-z]*c/) hasc = 1
      }
      if (hasc && j <= e) { EX[d, j] = 1; parsestr(A[d, j], d + 1); SK = "" }
      else if (j > e) SK = "sh"
      break
    } else if (b == "find") {
      for (j = s + 1; j <= e && A[d, j] !~ /^-(exec|execdir|ok|okdir)$/; j++) chk(A[d, j])
      if (j > e) break
      for (i = j + 1; i <= e && A[d, i] != ";" && A[d, i] != "+"; i++) ;
      s = j + 1; e = i - 1
    } else break
  }
  for (i = 1; i < s; i++) if (!EX[d, i]) chk(A[d, i])
  if (s > e) return
  cmd = bn(A[d, s])
  if (cmd ~ /^(python[0-9.]*|node|ruby|perl|php|deno|bun|tsx|ts-node|osascript)$/) SK = "interp"
  if (cmd == "echo" || cmd == "printf") for (i = s + 1; i <= e; i++) EX[d, i] = 1
  else if (cmd ~ /^(grep|egrep|fgrep|zgrep|rg|ag|ack)$/ || (cmd == "git" && A[d, s + 1] == "grep")) {
    np = 0; j = (cmd == "git") ? s + 2 : s + 1
    for (i = j; i <= e; i++) {
      w = A[d, i]
      if (w == "--") { if (!np && i < e) EX[d, i + 1] = 1; break }
      if (w ~ /^(-e|--regexp)$/) { EX[d, ++i] = 1; np = 1 }
      else if (w ~ /^(-e.|--regexp=)/) { EX[d, i] = 1; np = 1 }
      else if (w ~ /^(-[ABCmfdDgtTMj]|--(file|context|after-context|before-context|max-count|glob|type|type-not|max-columns|threads|include|exclude|exclude-dir))$/) i++
      else if (w !~ /^-/ && !np) { EX[d, i] = 1; np = 1 }
    }
  } else if (cmd == "git") {
    for (i = s + 1; i <= e; i++) if (A[d, i] ~ /^(-m|--message)$/) EX[d, ++i] = 1; else if (A[d, i] ~ /^(--message=|-m.)/) EX[d, i] = 1
  } else if (cmd == "gh") {
    for (i = s + 1; i <= e; i++) if (A[d, i] ~ /^(-b|--body|-t|--title|--notes)$/) EX[d, ++i] = 1; else if (A[d, i] ~ /^--(body|title|notes)=/) EX[d, i] = 1
  }
  np = 0; cl = ""; prev = ""; irr = 0
  for (i = s; i <= e; i++) {
    w = A[d, i]
    if (!EX[d, i]) chk(w)
    if (i == s) continue
    if (prev ~ /^(--url|-u|--provider\.cluster)$/) cl = w
    else if (w ~ /^--(url|provider\.cluster)=/) { cl = w; sub(/^[^=]*=/, "", cl) }
    else if (w ~ /^-u./) cl = substr(w, 3)
    if (w ~ /^--final/ || w == "--bypass-warning") irr = 1
    if (w ~ /^-/ || prev ~ /^(-u|--url|-k|--keypair|-C|--config|--commitment|--ws|--output|--fee-payer|--program-id|--provider\.cluster|--provider\.wallet|--with-compute-unit-price|--with-compute-unit-limit)$/) { prev = w; continue }
    prev = w; if (++np == 1) p1 = w; else if (np == 2) p2 = w
  }
  if (cmd == "gh") for (i = s + 1; i < e; i++) if (A[d, i] == "auth" && A[d, i + 1] == "token" && HIT == "") HIT = "gh auth token"
  if (!(cmd == "solana" || cmd == "anchor" || cmd == "spl-token")) return
  if (!(((cmd == "solana" || cmd == "anchor") && p1 == "program" && p2 ~ /^(deploy|write-buffer|upgrade|extend|migrate|close|set-upgrade-authority|set-buffer-authority)$/) || (cmd == "solana" && p1 == "program-v4" && p2 ~ /^(deploy|retract|transfer-authority|finalize)$/) || (cmd == "anchor" && p1 ~ /^(deploy|upgrade)$/) || (cmd == "solana" && p1 ~ /^(transfer|withdraw-stake|withdraw-from-vote-account|withdraw-from-nonce-account)$/) || (cmd == "spl-token" && p1 ~ /^(transfer|burn|close|authorize)$/))) return
  if (p2 == "finalize") irr = 1
  if (cmd == "spl-token" && p1 == "authorize") for (i = s + 1; i <= e; i++) if (A[d, i] == "--disable") irr = 1
  if (irr) IRR = 1
  gsub(/[^A-Za-z0-9:\/._?=&-]/, "", cl)
  if (CH == "" || (!CHM && tolower(cl) ~ /mainnet|^m$/)) { CH = cmd " " cl; CHM = (tolower(cl) ~ /mainnet|^m$/) }
}
function unjson(t, o, i, L, c, nx) {
  o = ""; L = length(t)
  for (i = 1; i <= L; i++) {
    c = substr(t, i, 1)
    if (c != "\\") { o = o c; continue }
    nx = substr(t, ++i, 1)
    if (nx == "n") o = o "\n"; else if (nx == "t") o = o "\t"; else if (nx == "r") ; else if (nx == "u") o = o "\\u"; else o = o nx
  }
  return o
}
BEGIN {
  SQ = "\047"; DQ = "\042"
  SECRE = "\\.ssh(/|$)|\\.gnupg|\\.aws(/|$)|\\.config/solana/id\\.json|\\.npmrc|\\.git-credentials|\\.netrc|\\.cargo/credentials|\\.docker/config\\.json|\\.config/gh/hosts|\\.kube/config|\\.pypirc|\\.gem/credentials|^--show-token|Application[\\\\ ]+Support/Google/Chrome|Application[\\\\ ]+Support/BraveSoftware|Application[\\\\ ]+Support/Microsoft[\\\\ ]+Edge|Application[\\\\ ]+Support/Firefox|Application[\\\\ ]+Support/Chromium|Application[\\\\ ]+Support/Vivaldi|Application[\\\\ ]+Support/Arc|Application[\\\\ ]+Support/com\\.operasoftware|\\.config/google-chrome|\\.config/BraveSoftware|\\.config/microsoft-edge|\\.mozilla/firefox|\\.config/chromium|\\.config/vivaldi|\\.config/opera|AppData/Local/Google/Chrome|AppData/Local/BraveSoftware|AppData/Local/Microsoft/Edge|AppData/Roaming/Mozilla/Firefox|AppData/Local/Chromium|AppData/Local/Vivaldi|AppData/Roaming/Opera[\\\\ ]+Software|Local[\\\\ ]+Extension[\\\\ ]+Settings|moz-extension"
}
{ LS[0, NR] = $0 }
END {
  LC[0] = NR
  if (J) { T = LS[0, 1]; for (i = 2; i <= NR; i++) T = T "\n" LS[0, i]; parsestr(unjson(T), 0) } else parse(0)
  if (HIT != "") print "SECRET " HIT
  if (IRR) print "IRREV"
  if (CH != "") print "CHAIN " CH
  if (!BAD) print "PARSED"
}' 2>/dev/null)
case $OUT in
  *PARSED*) ;;
  *) printf '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"ask","permissionDecisionReason":"%s"}}\n' "The kit safety hook could not parse this command. Check it before approving."; exit 0 ;;
esac
HIT=$(printf '%s\n' "$OUT" | sed -n 's/^SECRET //p')
if [ -n "$HIT" ]; then
  echo "🛑 Blocked: reading private keys, wallet vaults or credentials is not allowed ($HIT). Use \`solana address\` for the pubkey; ask the user to run anything that needs the secret." >&2
  exit 2
fi
case $OUT in *IRREV*)
  echo "🛑 Blocked: irreversible on-chain action (--final, program close --bypass-warning, program-v4 finalize or authorize --disable). If the user wants it, they run it themselves outside Claude." >&2
  exit 2 ;;
esac
SEG=$(printf '%s\n' "$OUT" | sed -n 's/^CHAIN //p')
[ -n "$SEG" ] || exit 0
BIN=${SEG%% *} CL=${SEG#* } SRC='command flag'
if [ -z "$CL" ]; then
  case $BIN in
    anchor) SRC=Anchor.toml; CL=$(awk -F'"' '/^[[:space:]]*cluster[[:space:]]*=/{print $2; exit}' Anchor.toml 2>/dev/null) ;;
    *) SRC='solana config'; CL=$(solana config get json_rpc_url 2>/dev/null | awk '{print $NF}') ;;
  esac
fi
CL=$(printf '%s' "${CL#=}" | tr '[:upper:]' '[:lower:]' | sed -E 's#^([a-z]+://[^/?]+).*#\1#' | tr -cd 'a-z0-9:/._-')
case $CL in
  m|*mainnet*) R="MAINNET (from $SRC): spends real SOL or changes a live program. Approve only if the user asked for mainnet." ;;
  d|*devnet*) R="On-chain write to devnet (from $SRC)." ;;
  t|*testnet*) R="On-chain write to testnet (from $SRC)." ;;
  l|localnet|*localhost*|*127.0.0.1*) R="On-chain write to localnet (from $SRC)." ;;
  '') R='On-chain write to an unknown cluster (no --url, Anchor.toml or solana config found). Check the target before approving.' ;;
  *) R="On-chain write to $CL (from $SRC). Check the cluster before approving." ;;
esac
printf '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"ask","permissionDecisionReason":"%s"}}\n' "$R"
